def verify_isbn(isbn: str) -> str:
    # Check if the ISBN is in the correct format
    if not re.match(r"^\d{1,2}-\d{3}-\d{5}-\d$", isbn):
        return "Wrong format"

    # Extract the digits and checksum from the ISBN
    digits = isbn[:-1]
    checksum = isbn[-1]

    # Calculate the checksum
    sum = 0
    for i, digit in enumerate(digits):
        if i % 2 == 0:
            sum += int(digit)
        else:
            sum += int(digit) * 3
    checksum_calculated = (10 - (sum % 10)) % 10

    # Compare the checksum with the provided checksum
    if checksum == checksum_calculated:
        return "Right"
    else:
        return f"{digits}-{checksum_calculated}"

def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    aisle_matrix = [[0] * (N + 1) for _ in range(M + 1)]

    # Loop through each chatting pair and count the number of pairs that can be separated by adding an aisle in each position
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                aisle_matrix[i][j] += 1

    # Find the most effective positions for aisles, aiming to separate as many chatting pairs as possible
    row_indices = []
    col_indices = []
