        return 1
    if m == 1:
        return n
    return count_passing_ways(n - 1, m - 1) + count_passing_ways(n - 1, m)

def max_energy(beads):
    # Initialize the dynamic programming table
    dp = [[0] * len(beads) for _ in range(len(beads))]

    # Base case: single bead
    dp[0][0] = beads[0]

    # Fill in the table
    for i in range(1, len(beads)):
        for j in range(i):
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j + 1] + beads[i] * beads[j])

    # Return the maximum energy
    return max(dp[-1])

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        term = ''
        if coeff < 0:
            term += '-'
        elif i > 0:
            term += '+'
        if abs(coeff) != 1 or i == 0:
            term += str(abs(coeff))
        if i > 1:
            term += 'x^' + str(i)
        elif i == 1:
            term += 'x'
        terms.append(term)
    return ''.join(terms)

def select_volunteers(n, m, applicants):
    # Sort the applicants based on their test scores in descending order
    applicants.sort(key=lambda x: x[1], reverse=True)

    # Calculate the interview score cutoff as 150% of the planned number of recruits, rounded down
    cutoff = int(1.5 * m)

    # Create a list to store the qualified applicants
    qualified = []

    # Iterate through the applicants and add those with scores equal to or higher than the cutoff to the list
    for app in applicants:
        if app[1] >= cutoff:
