    while True:
        harmonic_sum = sum(1 / i for i in range(1, n + 1))
        if harmonic_sum > k:
            return n
        n += 1

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

