def next_permutation(perm: list) -> bool:
    # Find the first number from the end that is smaller than the number following it
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    else:
        # If no such number is found, the input is the last permutation
        return False

    # Find the smallest number that is larger and comes after it
    for j in range(i + 1, len(perm)):
        if perm[j] > perm[i]:
            break

    # Swap the two numbers
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the order of numbers after the original first smaller number
    perm[i + 1:] = perm[i + 1:][::-1]

    return True

def jinjin_savings_plan(budgets: List[int]) -> int:
    total_savings = 0
    for i, budget in enumerate(budgets):
        if budget >= 100:
            savings = budget // 100 * 100
            total_savings += savings
        else:
            return -i
    total_savings *= 1.2
    return int(total_savings)

def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14
    total_moves = 0
    for i in range(n):
        total_moves += hanoi_double_iterative(i)
    return total_moves
